#!/usr/bin/env python3
"""Apply the v7 corrections to a copy of the v6 source (body only).

Every replacement must match exactly once in the body (after \\begin{document});
the hover-tip definitions in the preamble are regenerated by build_v7.py.
"""
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[1]
TEX = ROOT / 'manuscript' / 'prime_corrected_clock_v7.tex'
src = TEX.read_text()
head, sep, body = src.partition('\\begin{document}')
assert sep

def rep(old, new, count=1):
    global body
    n = body.count(old)
    if n != count:
        sys.exit(f'expected {count} match(es), found {n}:\n{old[:160]}')
    body = body.replace(old, new)

def rep_re(pattern, new):
    global body
    m = list(re.finditer(pattern, body, re.S))
    if len(m) != 1:
        sys.exit(f'regex expected 1 match, found {len(m)}: {pattern[:120]}')
    body = body[:m[0].start()] + new + body[m[0].end():]

